// src/components/UpdateProfile/UpdateProfile.js
import React, { useState, useEffect } from "react";
import axios from "axios";
import { getBaseURL } from "../../apiConfig"; // adapte selon ta config

const UpdateProfile = ({ userId }) => {
  const [userData, setUserData] = useState({
    fname: "",
    lname: "",
    email: "",
    // Ajouter d’autres champs au besoin
  });

  useEffect(() => {
    // Au montage, on récupère les infos de l’utilisateur
    if (userId) {
      axios
        .get(`${getBaseURL()}api/users/${userId}`)
        .then((res) => {
          // Suppose que res.data est un objet { fname, lname, email, etc. }
          setUserData({
            fname: res.data.fname || "",
            lname: res.data.lname || "",
            email: res.data.email || "",
            // Autres champs
          });
        })
        .catch((err) => console.error("Error fetching user:", err));
    }
  }, [userId]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setUserData((prevState) => ({
      ...prevState,
      [name]: value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Appel PUT pour mettre à jour l’utilisateur
    axios
      .put(`${getBaseURL()}api/users/update/${userId}`, userData)
      .then(() => {
        alert("Profile updated successfully!");
        // Possibilité de rediriger ailleurs, ex: navigate("/")
      })
      .catch((err) => console.error("Error updating profile:", err));
  };

  return (
    <div>
      <h2>Update Profile</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>First Name</label>
          <input
            name="fname"
            type="text"
            value={userData.fname}
            onChange={handleChange}
          />
        </div>

        <div>
          <label>Last Name</label>
          <input
            name="lname"
            type="text"
            value={userData.lname}
            onChange={handleChange}
          />
        </div>

        <div>
          <label>Email</label>
          <input
            name="email"
            type="email"
            value={userData.email}
            onChange={handleChange}
          />
        </div>

        {/* Ajouter d’autres champs (password, phone, etc.) */}

        <button type="submit">Save Changes</button>
      </form>
    </div>
  );
};

export default UpdateProfile;
